import React, { useState, useEffect, useRef } from 'react';
import { debounce } from 'lodash';
import { TextField, Paper, List, ListItem } from '@mui/material';
import * as api from '../services/api';

// value와 onChange prop 추가
const FoodAutocomplete = ({ onSelect, value = '', onChange }) => {
  const [query, setQuery] = useState(value);
  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef(null);

  // value prop이 변경될 때 query 상태 업데이트
  useEffect(() => {
    setQuery(value);
  }, [value]);

  // debounce 함수로 API 호출 최적화
  const fetchSuggestions = debounce(async (input) => {
    if (input.length >= 1) {    // 한글자만 입력해도 자동완성 시도
      const data = await api.getFoodAutocomplete(input);
      setSuggestions(data);
      setShowSuggestions(true);
    } else {
      setSuggestions([]);
      setShowSuggestions(false);
    }
  }, 300);

  // 입력값 변경 처리
  const onInputChange = (e) => {
    const newValue = e.target.value;
    setQuery(newValue);
    fetchSuggestions(newValue);
    
    // onChange prop이 있으면 호출
    if (onChange) {
      onChange(newValue);
    }
    
    // onSelect prop이 있으면 호출
    if (onSelect) {
      onSelect(newValue);
    }
  };

  // 제안 선택 처리
  const onSuggestionClick = (suggestion) => {
    setQuery(suggestion);
    setSuggestions([]);
    setShowSuggestions(false);
    
    // onChange prop이 있으면 호출
    if (onChange) {
      onChange(suggestion);
    }
    
    // onSelect prop이 있으면 호출
    if (onSelect) {
      onSelect(suggestion);
    }
  };

  // 외부 클릭 시 제안 닫기
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [wrapperRef]);

  return (
    <div className="relative" ref={wrapperRef} style={{ position: 'relative', width: '100%' }}>
      <TextField
        fullWidth
        label="식품명"
        value={query}
        onChange={onInputChange}
        placeholder="예: 사과"
        required
        helperText="검색할 식품명을 입력하세요"
        autoComplete="off"
      />
      {showSuggestions && suggestions.length > 0 && (
        <Paper 
          elevation={3} 
          sx={{ 
            position: 'absolute', 
            width: '100%',
            minWidth: '100%',  // 최소 너비 보장
            left: 0,
            right: 0,  // 오른쪽도 0으로 설정
            top: 'calc(100% + 4px)',  // 입력 필드 바로 아래
            zIndex: 9999,  // z-index 증가
            maxHeight: '400px',  // 높이 더 증가
            overflowY: 'auto',
            overflowX: 'hidden',
            border: '1px solid #e0e0e0',
            backgroundColor: 'white',  // 배경색 명시
            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)'  // 그림자 추가
          }}
        >
          <List sx={{ py: 0, width: '100%' }}>
            {suggestions.map((item, index) => (
              <ListItem 
                key={index}
                button
                onClick={() => onSuggestionClick(item)}
                sx={{ 
                  cursor: 'pointer', 
                  py: 1.5,  // 패딩 증가
                  px: 2,
                  minHeight: 'auto',
                  width: '100%',  // 전체 너비 사용
                  display: 'block',  // 블록 요소로 변경
                  textAlign: 'left',  // 텍스트 왼쪽 정렬
                  whiteSpace: 'normal',  // 줄바꿈 허용
                  wordBreak: 'break-word',  // 긴 단어도 줄바꿈
                  fontSize: '14px',  // 폰트 크기 명시
                  lineHeight: 1.5,  // 줄 간격
                  '&:hover': { backgroundColor: 'rgba(0, 0, 0, 0.04)' }
                }}
              >
                {item}
              </ListItem>
            ))}
          </List>
        </Paper>
      )}
    </div>
  );
};

export default FoodAutocomplete;